import org.junit.jupiter.api.Test;

/** Deterministic tripwire for repeated whole-subtree safety walks during filter planning. */
class QuerySafetyAnalysisReuseTest {

	private static final int FILTERS = 32;
	private static final int RIGHT_PATTERNS = 48;
	private static final String FUNCTION_URI = "urn:test:query-safety:counting-determinism";

	@Test
	void filterPlanningClassifiesAnUnchangedLargeJoinOperandOnce() {
		CountingDeterministicFunction function = new CountingDeterministicFunction();
		FunctionRegistry registry = FunctionRegistry.getInstance();
		registry.add(function);
		try {
			QueryRoot root = new QueryRoot(createNestedFilteredJoin());
			QueryEvaluationUtility.pinFunctions(root);
			function.determinismChecks.set(0);

			new FilterOptimizer(null, false, false).optimize(root, null, EmptyBindingSet.getInstance());

			assertThat(function.determinismChecks.get())
					.as("safety planning must reuse the summary for the unchanged right subtree across filters")
					.isLessThanOrEqualTo(5);
		} finally {
			registry.remove(function);
		}
	}

	@Test
	void precompilationClassifiesAnUnchangedLargeJoinOperandOnce() {
		CountingDeterministicFunction function = new CountingDeterministicFunction();
		FunctionRegistry registry = FunctionRegistry.getInstance();
		registry.add(function);
		try {
			QueryRoot root = new QueryRoot(createRightDeepJoin());
			QueryEvaluationUtility.pinFunctions(root);
			function.determinismChecks.set(0);

			new DefaultEvaluationStrategy(new EmptyTripleSource(), null).precompile(root);

			assertThat(function.determinismChecks.get())
					.as("precompilation must reuse the safety summary across nested joins")
					.isLessThanOrEqualTo(5);
		} finally {
			registry.remove(function);
		}
	}

	@Test
	void phaseSnapshotRefreshTracksChangedErrorAndInjectionFacts() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		Filter filter = new Filter(statementPattern("a", vf), new Compare(Var.of("outer"),
				new ValueConstant(vf.createLiteral("value")), Compare.CompareOp.EQ));
		QueryRoot root = new QueryRoot(filter);

		QueryEvaluationUtility.withQuerySafetySnapshot(root, () -> {
			assertThat(QueryEvaluationUtility.permitsBindingInjection(filter, Set.of("outer"))).isFalse();
			assertThat(QueryEvaluationUtility.permitsBindingInjection(filter, Set.of("other"))).isTrue();

			filter.setCondition(new Compare(Var.of("other"), new ValueConstant(vf.createLiteral("value")),
					Compare.CompareOp.EQ));
			QueryEvaluationUtility.refreshQuerySafetySnapshot(filter);

			assertThat(QueryEvaluationUtility.permitsBindingInjection(filter, Set.of("outer")))
					.as("only the changed expression's exact variable set should affect injection safety")
					.isTrue();
			assertThat(QueryEvaluationUtility.permitsBindingInjection(filter, Set.of("other"))).isFalse();
			assertThat(QueryEvaluationUtility.permitsBindingInjection(filter, Set.of("unrelated"))).isTrue();

			Join joined = new Join(statementPattern("left", vf), statementPattern("right", vf));
			QueryRoot serviceRoot = new QueryRoot(joined);
			QueryEvaluationUtility.refreshQuerySafetySnapshot(serviceRoot);
			assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(serviceRoot)).isFalse();
			assertThat(QueryEvaluationUtility.usesMappingParameterizedEvaluation(joined)).isFalse();

			Service service = new Service(Var.of("endpoint"), statementPattern("remote", vf), "", Map.of(), null,
					false);
			joined.replaceChildNode(joined.getRightArg(), service);
			QueryEvaluationUtility.refreshQuerySafetySnapshot(joined);

			assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(serviceRoot)).isTrue();
			assertThat(QueryEvaluationUtility.canDiscardWithoutEvaluation(serviceRoot)).isFalse();
			assertThat(QueryEvaluationUtility.usesMappingParameterizedEvaluation(joined)).isTrue();
			assertThat(QueryEvaluationUtility.isRepeatable(serviceRoot)).isFalse();
			return null;
		});
	}

	private static TupleExpr createRightDeepJoin() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		TupleExpr right = new Extension(statementPatternWithSharedVariable("r", vf),
				new ExtensionElem(new FunctionCall(FUNCTION_URI), "marker"));
		for (int i = RIGHT_PATTERNS - 1; i >= 0; i--) {
			right = new Join(statementPatternWithSharedVariable("r" + i, vf), right);
		}
		StatementPattern left = statementPatternWithSharedVariable("left", vf);
		return new Join(left, right);
	}

	private static TupleExpr createNestedFilteredJoin() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		TupleExpr right = statementPattern("r0", vf);
		for (int i = 1; i < RIGHT_PATTERNS; i++) {
			right = new Join(right, statementPattern("r" + i, vf));
		}
		right = new Extension(right, new ExtensionElem(new FunctionCall(FUNCTION_URI), "marker"));

		TupleExpr result = new Join(
				new StatementPattern(Var.of("x"), new Var("leftPredicate", vf.createIRI("urn:left")),
						Var.of("leftObject")),
				right);
		for (int i = 0; i < FILTERS; i++) {
			result = new Filter(result, new SameTerm(Var.of("x"), new ValueConstant(vf.createIRI("urn:left:" + i))));
		}
		return result;
	}

	private static StatementPattern statementPattern(String name, ValueFactory vf) {
		return new StatementPattern(Var.of(name + "s"), new Var(name + "p", vf.createIRI("urn:" + name)),
				Var.of(name + "o"));
	}

	private static StatementPattern statementPatternWithSharedVariable(String name, ValueFactory vf) {
		return new StatementPattern(Var.of("shared"), new Var(name + "p", vf.createIRI("urn:" + name)),
				Var.of(name + "o"));
	}

	private static final class CountingDeterministicFunction implements Function {
		private final AtomicInteger determinismChecks = new AtomicInteger();

		@Override
		public String getURI() {
			return FUNCTION_URI;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) {
			return valueFactory.createLiteral("value");
		}

		@Override
		public Determinism getDeterminism() {
			determinismChecks.incrementAndGet();
			return Determinism.DETERMINISTIC;
		}
	}
}
